def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    t = int(data[1])
    a = list(map(int, data[2:2+t]))

    r = {}
    c = {}
    d = {1: 0, 2: 0}

    ans = -1
    for l in range(t):
        ai = a[l]
        i = (ai - 1) // n
        j = (ai - 1) % n

        if i not in r:
            r[i] = 1
        else:
            r[i] += 1
        if r[i] == n:
            ans = l + 1
            break

        if j not in c:
            c[j] = 1
        else:
            c[j] += 1
        if c[j] == n:
            ans = l + 1
            break

        if (ai - 1) % (n + 1) == 0:
            d[1] += 1
            if d[1] == n:
                ans = l + 1
                break

        if (ai - 1) % (n - 1) == 0 and (ai - 1) // (n - 1) < n and (ai - 1) // (n - 1) > 0:
            d[2] += 1
            if d[2] == n:
                ans = l + 1
                break

    print(ans)
